-- Seeds public.rule_packs from the core rule pack files:
--   packages/core/rule-packs/orthodox.v0.1.json
--   packages/core/rule-packs/islamic.v0.1.json
-- Generated: JSON.stringify(JSON.parse(file)) embedded verbatim. Re-run the generator, do not hand-edit.
-- Idempotent: safe to apply again on a database that already has the rows.

insert into public.rule_packs (id, version, data)
values ('orthodox', '0.1', $pack${"$comment":"Orthodox fasting rules as data (D-06). Dates are Gregorian MM-DD, already shifted +13 days from the Julian church calendar (valid 1901-2099); 'os' is the old-style date as the source states it. 'easter' offsets are days from Orthodox Easter. Weekday keys: mon..sun. Evaluation order: free (first match returns) -> periods + oneDay + weekly (strictest wins; oneDay suppresses the weekly reason) -> relax (only if stricter than riba) -> user strictness cap. src: 'svetosavlje' = the page below, 'domain' = docs/DOMAIN.md section 2 (not on that page).","id":"orthodox","version":"0.1","calendar":"julian","dateStyle":"gregorian","julianOffsetDays":13,"validYears":[1901,2099],"sources":{"svetosavlje":{"title":"Pravilo posta za celu godinu","url":"https://svetosavlje.org/pravilo-posta-za-celu-godinu/","retrieved":"2026-11-23","covers":"weekday levels of the four fasts, the Wednesday and Friday rule, fast-free weeks, fish days"},"domain":{"ref":"docs/DOMAIN.md section 2 (from docs/reference/engine.js)","covers":"fast boundaries, one-day fasts, Bogojavljenje, Vavedenje, Sveti Nikola"}},"free":[{"id":"svjatki","name":"Svjatki","sub":"od Božića do Krstovdana, mrsna sedmica","fixed":["01-07","01-17"],"os":["12-25","01-04"],"level":"mrsno","src":"svetosavlje"},{"id":"bogojavljenje","name":"Bogojavljenje","sub":"praznik, nema posta","fixed":"01-19","os":"01-06","level":"mrsno","src":"domain"},{"id":"svijetla","name":"Svijetla sedmica","sub":"sedmica poslije Vaskrsa, mrsna","easter":[0,6],"level":"mrsno","src":"svetosavlje"},{"id":"trojicina","name":"Trojičina sedmica","sub":"sedmica poslije Duhova, mrsna","easter":[50,56],"level":"mrsno","src":"svetosavlje"},{"id":"mitar","name":"Sedmica Mitara i fariseja","sub":"mrsna sedmica","easter":[-69,-64],"level":"mrsno","src":"svetosavlje"},{"id":"bijela","name":"Bijela sedmica","sub":"bez mesa; mliječno, jaja i riba su dozvoljeni","easter":[-55,-49],"level":"bezmesa","src":"svetosavlje"}],"periods":[{"id":"bozicni","name":"Božićni post","sub":"28.11. – 6.1.","fixed":["11-28","01-06"],"os":["11-15","12-24"],"src":"svetosavlje","segments":[{"fixed":["11-28","12-30"],"os":["11-15","12-17"],"week":{"mon":"voda","tue":"ulje","wed":"voda","thu":"ulje","fri":"voda","sat":"riba","sun":"riba"}},{"fixed":["12-31","01-06"],"os":["12-18","12-24"],"week":{"mon":"voda","tue":"ulje","wed":"voda","thu":"ulje","fri":"voda","sat":"ulje","sun":"ulje"}}]},{"id":"veliki","name":"Veliki post","sub":"od Čistog ponedjeljka do Velike subote","easter":[-48,-1],"src":"svetosavlje","week":{"mon":"voda","tue":"voda","wed":"voda","thu":"voda","fri":"voda","sat":"ulje","sun":"ulje"}},{"id":"petrovski","name":"Petrovski post","sub":"od Vaskrsa + 57 dana do 11.7.","easterFrom":57,"fixedTo":"07-11","osTo":"06-28","src":"svetosavlje","week":{"mon":"voda","tue":"ulje","wed":"voda","thu":"ulje","fri":"voda","sat":"riba","sun":"riba"}},{"id":"gospojinski","name":"Gospojinski post","sub":"14.8. – 27.8.","fixed":["08-14","08-27"],"os":["08-01","08-14"],"src":"svetosavlje","week":{"mon":"voda","tue":"voda","wed":"voda","thu":"voda","fri":"voda","sat":"ulje","sun":"ulje"}}],"oneDay":[{"id":"badnji","name":"Badnji dan","sub":"posljednji dan Božićnog posta","fixed":"01-06","os":"12-24","level":"voda","keepsPeriod":"bozicni","src":"domain"},{"id":"krstovdan","name":"Krstovdan","sub":"jednodnevni post","fixed":"01-18","os":"01-05","level":"voda","src":"domain"},{"id":"usekovanje","name":"Usekovanje","sub":"jednodnevni post","fixed":"09-11","os":"08-29","level":"voda","src":"domain"},{"id":"vozdvizenje","name":"Krstovdan (Vozdviženje)","sub":"jednodnevni post","fixed":"09-27","os":"09-14","level":"voda","src":"domain"}],"weekly":{"days":{"wed":"Srijeda","fri":"Petak"},"sub":"posni dan u sedmici, strože pravilo pobjeđuje","level":"voda","src":"svetosavlje","overrides":[{"id":"tomina-duhovi","name":"Od Tomine nedjelje do Duhova","sub":"srijeda i petak na ulju","easter":[7,49],"level":"ulje","src":"svetosavlje"}]},"relax":[{"id":"vavedenje","name":"Vavedenje","fixed":"12-04","os":"11-21","to":"riba","src":"domain"},{"id":"nikola","name":"Sveti Nikola","fixed":"12-19","os":"12-06","to":"riba","src":"domain"},{"id":"blagovijesti","name":"Blagovijesti","fixed":"04-07","os":"03-25","to":"riba","src":"svetosavlje"},{"id":"cvijeti","name":"Cvijeti","easter":-7,"to":"riba","src":"svetosavlje"},{"id":"prepolovljenje","name":"Prepolovljenje","easter":24,"to":"riba","src":"svetosavlje"},{"id":"odanije","name":"Odanije Vaskrsa","easter":38,"to":"riba","src":"svetosavlje"},{"id":"petrovdan","name":"Petrovdan","fixed":"07-12","os":"06-29","to":"riba","src":"svetosavlje"},{"id":"preobrazenje","name":"Preobraženje","fixed":"08-19","os":"08-06","to":"riba","src":"svetosavlje"},{"id":"gospojina","name":"Velika Gospojina","fixed":"08-28","os":"08-15","to":"riba","src":"svetosavlje"}],"relaxSub":"praznik, olakšica na ribu"}$pack$::jsonb)
on conflict (id) do update
  set version = excluded.version, data = excluded.data, published_at = now();

insert into public.rule_packs (id, version, data)
values ('islamic', '0.1', $pack${"$comment":"Known Hijri month starts (day 1, Gregorian, Europe/Podgorica). Between two known starts the months in a gap take tabular lengths, and the last month in the gap absorbs the remainder; every month must come out at 29 or 30 days. After the last known start the calendar continues as tabular Hijri shifted to match it, so dates stay continuous. Before the first known start it is plain tabular. The user shift (ramadanShift) still applies on top. Extend this file every year when the next calendar is published, then bump the version.","id":"islamic","version":"0.1","authority":"diyanet","sources":{"praznici":{"title":"Islamski praznici - Crna Gora (2027)","url":"https://prayer-times.e-corlu.com/?a=montenegro&id=249&p=20&l=9","retrieved":"2026-11-23","copy":"docs/reference/sources/diyanet-islamski-praznici-crna-gora-2026-11-23.md"},"podgorica":{"title":"Ramazanska vaktija 2027 Podgorica (Izvor: Diyanet)","url":"https://ramadan.e-corlu.com/?a=podgorica&id=14875&l=9","retrieved":"2026-11-23","copy":"docs/reference/sources/diyanet-ramazan-podgorica-2026-11-23.md"}},"monthStarts":[{"hijri":"1448-06","start":"2026-11-10","src":"podgorica","from":"2026-11-23 is printed as 14 Džumade-l-uhra 1448"},{"hijri":"1448-07","start":"2026-12-10","src":"praznici","from":"Noć Mi'radža 2027-01-04 = 26 Redžeb; Početak blagoslovljenih mjeseci 2026-12-10"},{"hijri":"1448-08","start":"2027-01-09","src":"praznici","from":"Prva teravija 2027-02-07 = 30 Ša'ban; Noć Berata 2027-01-27 = 19 Ša'ban"},{"hijri":"1448-09","start":"2027-02-08","src":"praznici","from":"Početak Ramazana 2027-02-08 = 1 Ramazan; Ramadan 1448 lasts 29 days"},{"hijri":"1448-10","start":"2027-03-09","src":"praznici","from":"Ramazanski bajram 2027-03-09 = 1 Ševval"},{"hijri":"1448-12","start":"2027-05-07","src":"praznici","from":"Kurban bajram 2027-05-16 = 10 Zu-l-hidždže"},{"hijri":"1449-01","start":"2027-06-06","src":"praznici","from":"Islamska nova godina 2027-06-06 = 1 Muharrem; Dan Ašure 2027-06-15 = 10 Muharrem"},{"hijri":"1449-02","start":"2027-07-05","src":"praznici","from":"derived: 1 Muharrem to 1 Rebiu-l-evvel is 58 days, which only splits as 29 + 29"},{"hijri":"1449-03","start":"2027-08-03","src":"praznici","from":"Mevlud 2027-08-13 = 11 Rebiu-l-evvel"},{"hijri":"1449-07","start":"2027-11-29","src":"praznici","from":"derived: Početak blagoslovljenih mjeseci 2027-11-29 and Noć Mi'radža 2027-12-24 (26 Redžeb), no Hijri dates printed"}]}$pack$::jsonb)
on conflict (id) do update
  set version = excluded.version, data = excluded.data, published_at = now();
